import type {
  AnyPropertyEditorOverride,
  AnyPropertySchema,
} from '@/data/api'
import {propertyDefinitionBlockId} from '@/data/definitionSeeds'
import type {PropertyDefinitionMetadata} from '@/data/propertyDefinitionMetadata'
import {isPropertySeedDeclaration, type AnyPropertySeedDeclaration} from '@/data/propertySeeds'

/** A block-built behavioral entry kept beside its durable field identity.
 * The public ambient registry is name-keyed; this internal form prevents that
 * lossy projection from becoming the resolver's source of identity. */
export interface ParsedPropertyDefinition {
  readonly metadata: PropertyDefinitionMetadata
  readonly schema?: AnyPropertySchema
}

/** A live `property-schema` block whose metadata does not parse (an empty
 * name, a change scope that is not one, a flag that does not decode). It is
 * no definition to the registry, so a field row targeting it is an honest
 * unknown-field row (§9) — and the outline SQL, which recognizes definitions
 * from `block_types` tags, has to be told so. */
export interface UnparseablePropertyDefinition {
  readonly unparseable: {readonly fieldId: string; readonly workspaceId: string}
}

/** What the user-schemas projector publishes per `property-schema` block. */
export type ProjectedPropertyDefinition =
  | ParsedPropertyDefinition
  | UnparseablePropertyDefinition

export const isParsedPropertyDefinition = (
  projected: ProjectedPropertyDefinition,
): projected is ParsedPropertyDefinition => 'metadata' in projected

export const projectedPropertyDefinitionFieldId = (
  projected: ProjectedPropertyDefinition,
): string => isParsedPropertyDefinition(projected)
  ? projected.metadata.fieldId
  : projected.unparseable.fieldId

/** Fold every source's projected definitions into one entry per field id.
 *  Last-wins, as for every keyed registry facet, except that a parsed
 *  definition outranks an unparseable marker for the same id in either order:
 *  a source that CAN define the id answers for it over one that could not read
 *  the block. That keeps `definitionsByFieldId` and `unparseableDefinitionIds`
 *  disjoint whatever the contribution order. */
export const combineProjectedPropertyDefinitions = (
  values: readonly ProjectedPropertyDefinition[],
): ReadonlyMap<string, ProjectedPropertyDefinition> => {
  const out = new Map<string, ProjectedPropertyDefinition>()
  for (const value of values) {
    const key = projectedPropertyDefinitionFieldId(value)
    const existing = out.get(key)
    if (existing !== undefined) {
      const parsedNow = isParsedPropertyDefinition(value)
      if (isParsedPropertyDefinition(existing) && !parsedNow) continue
      if (isParsedPropertyDefinition(existing) === parsedNow) {
        console.warn(
          `[data.projected-property-definitions] duplicate registration for "${key}"; ` +
          'last-wins per facet convention',
        )
      }
    }
    out.set(key, value)
  }
  return out
}

export interface PropertyDefinitionRegistrySnapshot {
  readonly workspaceId: string
  readonly schemas: ReadonlyMap<string, AnyPropertySchema>
  readonly definitionsByFieldId: ReadonlyMap<string, PropertyDefinitionMetadata>
  /** Blocks tagged `property-schema` here that are NOT in
   *  `definitionsByFieldId` — see {@link UnparseablePropertyDefinition}. */
  readonly unparseableDefinitionIds: ReadonlySet<string>
  readonly definitionsByName: ReadonlyMap<string, readonly PropertyDefinitionMetadata[]>
  readonly schemasByFieldId: ReadonlyMap<string, AnyPropertySchema>
  readonly seedsByKey: ReadonlyMap<string, AnyPropertySeedDeclaration>
  readonly seedsByName: ReadonlyMap<string, readonly AnyPropertySeedDeclaration[]>
}

/**
 * Every definition claiming `name`, by durable fieldId, in the order the
 * resolver would prefer them: block-built definitions first, then seed
 * DECLARATIONS whose row has not materialized yet.
 *
 * Must agree with `SnapshotPropertySchemaResolver.resolveName`, which falls
 * back to `seedsByName` when no block owns the name — so reading
 * `definitionsByName` alone reports a registered-but-unmaterialized seed's name
 * as unclaimed. For a rename refusal that is the dangerous direction: the name
 * reads as free and the re-key writes under a key the seed owns, which for a
 * kernel seed like `types` is the type-membership cell of every consuming
 * parent. Deduped by fieldId, since a materialized seed appears in both maps.
 */
export const propertyDefinitionClaimantsForName = (
  snapshot: PropertyDefinitionRegistrySnapshot,
  name: string,
): readonly string[] => {
  const claimants: string[] = []
  const seen = new Set<string>()
  const push = (fieldId: string): void => {
    if (seen.has(fieldId)) return
    seen.add(fieldId)
    claimants.push(fieldId)
  }
  for (const definition of snapshot.definitionsByName.get(name) ?? []) push(definition.fieldId)
  for (const seed of snapshot.seedsByName.get(name) ?? []) {
    push(propertyDefinitionBlockId(snapshot.workspaceId, seed.seedKey))
  }
  return claimants
}

export interface BuildPropertyDefinitionRegistryArgs {
  readonly workspaceId: string
  readonly projectedDefinitions: ReadonlyMap<string, ProjectedPropertyDefinition>
  readonly seeds: readonly AnyPropertySeedDeclaration[]
}

const pushGrouped = <T>(map: Map<string, T[]>, key: string, value: T): void => {
  const values = map.get(key) ?? []
  values.push(value)
  map.set(key, values)
}

const indexSeeds = (seeds: readonly AnyPropertySeedDeclaration[]) => {
  const byKey = new Map<string, AnyPropertySeedDeclaration>()
  const byName = new Map<string, AnyPropertySeedDeclaration[]>()
  for (const seed of seeds) {
    if (byKey.has(seed.seedKey)) {
      throw new Error(`[property definitions] duplicate seed key ${JSON.stringify(seed.seedKey)}`)
    }
    // v1 no-shadowing: property values are keyed by name, so two seeds sharing a
    // name is an inherent conflict (they would fight over one stored cell). Keep
    // the first and DROP the collider — loudly, so a plugin author notices and
    // namespaces (e.g. "myplugin:title"). We drop rather than throw: this runs on
    // every workspace registry rebuild, and the dynamic-extension loader keeps
    // the declared name while rewriting only the seedKey per block, so a
    // duplicate install (or two extensions colliding) must not crash the whole
    // workspace's schema registry.
    const existing = byName.get(seed.name)
    if (existing) {
      console.error(
        `[property definitions] dropping seed ${JSON.stringify(seed.seedKey)}: its name ` +
        `${JSON.stringify(seed.name)} collides with ${JSON.stringify(existing[0]!.seedKey)}; ` +
        `property names must be unique — namespace plugin seeds, e.g. "myplugin:name"`,
      )
      continue
    }
    byKey.set(seed.seedKey, seed)
    pushGrouped(byName, seed.name, seed)
  }
  return {byKey, byName}
}

/** The ONE seed each property NAME resolves to — the single owner of that
 *  rule, for callers that need the winner rather than the schema it publishes.
 *
 *  Not a detail a caller may re-derive: two seeds sharing a name is an
 *  inherent conflict (they fight over one stored cell) and `indexSeeds` keeps
 *  the FIRST and drops the rest. A caller assembling its own map with
 *  `set(name, seed)` gets last-wins and silently disagrees with the registry
 *  about which declaration is live. */
export const resolveSeedsByName = (
  seeds: readonly AnyPropertySeedDeclaration[],
): ReadonlyMap<string, AnyPropertySeedDeclaration> => {
  const resolved = new Map<string, AnyPropertySeedDeclaration>()
  for (const namedSeeds of indexSeeds(seeds).byName.values()) {
    if (namedSeeds.length === 1) resolved.set(namedSeeds[0]!.name, namedSeeds[0]!)
  }
  return resolved
}

/** Stage-0 behavioral registry used before a workspace is pinned. It exposes
 * declarations as plain entries but cannot produce identity-bearing values. */
export const buildUnboundPropertySchemas = (
  seeds: readonly AnyPropertySeedDeclaration[],
): ReadonlyMap<string, AnyPropertySchema> => resolveSeedsByName(seeds)

/**
 * The name a definition row answers to — the ONE spelling of this rule.
 *
 * A row whose `seedKey` is still DECLARED answers to the seed's declared name:
 * seeds are code-owned and non-renamable, so a stored name that has drifted (an
 * older client, an import, a sync from such a device) must not be allowed to
 * desync the indexes built from it.
 *
 * Everyone else answers to their stored name — including a DROPPED duplicate
 * seed's row, whose `seedKey` is absent from `seedsByKey` because `indexSeeds`
 * kept only the first of two same-name seeds. That row is not a current seed's
 * row, so it has no declared name to borrow; it keeps the one it stores.
 *
 * That last case is why this is shared rather than restated. A hand-rolled copy
 * in the synthesis pass read it as "no name at all", which made a live rival
 * invisible to the check that exists to find rivals.
 */
export const effectivePropertyDefinitionName = (
  row: {readonly name: string; readonly seedKey?: string},
  seedsByKey: ReadonlyMap<string, {readonly name: string}>,
): string => {
  const declared = row.seedKey !== undefined ? seedsByKey.get(row.seedKey) : undefined
  return declared?.name ?? row.name
}

const sameKeys = (
  a: ReadonlyMap<string, unknown> | ReadonlySet<string>,
  b: ReadonlyMap<string, unknown> | ReadonlySet<string>,
): boolean => {
  if (a.size !== b.size) return false
  for (const key of a.keys()) if (!b.has(key)) return false
  return true
}

/** Do two snapshots recognize the same field ids as definitions (§9
 *  condition 3)? The inputs to both views' answer: the parsed definitions, the
 *  unparseable blocks, the seed slots, and the workspace they belong to. A
 *  rename or a re-type changes none of them. */
export const sameFieldRecognition = (
  a: PropertyDefinitionRegistrySnapshot | null,
  b: PropertyDefinitionRegistrySnapshot | null,
): boolean => {
  if (a === b) return true
  if (a === null || b === null) return false
  return a.workspaceId === b.workspaceId
    && sameKeys(a.definitionsByFieldId, b.definitionsByFieldId)
    && sameKeys(a.unparseableDefinitionIds, b.unparseableDefinitionIds)
    && sameKeys(a.seedsByKey, b.seedsByKey)
}

/** Build one immutable-by-replacement workspace snapshot. Source precedence is
 * explicit during the cutover: block-built behavior replaces transitional
 * direct registrations, then a unique local declaration replaces its block
 * fallback. B2 adds name-winner filtering before boundary use. */
export const buildPropertyDefinitionRegistry = (
  args: BuildPropertyDefinitionRegistryArgs,
): PropertyDefinitionRegistrySnapshot => {
  const {byKey: seedsByKey, byName: seedsByDeclarationName} = indexSeeds(args.seeds)
  const definitionsByFieldId = new Map<string, PropertyDefinitionMetadata>()
  const unparseableDefinitionIds = new Set<string>()
  const definitionsByNameMutable = new Map<string, PropertyDefinitionMetadata[]>()
  const schemasByFieldId = new Map<string, AnyPropertySchema>()
  for (const projected of args.projectedDefinitions.values()) {
    if (!isParsedPropertyDefinition(projected)) {
      if (projected.unparseable.workspaceId === args.workspaceId) {
        unparseableDefinitionIds.add(projected.unparseable.fieldId)
      }
      continue
    }
    const raw = projected.metadata
    if (raw.workspaceId !== args.workspaceId) continue
    // Seeds are code-owned and non-renamable (user renames are deferred to
    // #288): a seed-provenanced row's effective name is always its declared
    // name. Normalizing here means a stored property-schema:name divergence
    // (an older client, an import, or a sync from such a device) cannot desync
    // the structural type/alias membership index or drop the field from a
    // static type's panel section.
    const effective = effectivePropertyDefinitionName(raw, seedsByKey)
    const definition = effective !== raw.name ? {...raw, name: effective} : raw
    definitionsByFieldId.set(definition.fieldId, definition)
    if (projected.schema) schemasByFieldId.set(definition.fieldId, projected.schema)
    // v1: code-owned seeds are unshadowable. A row competes for its name only if
    // it is a CURRENT seed's own row (its seedKey is still declared/kept) or a
    // non-seed row whose name doesn't collide with a kept seed's declared name.
    // Two exclusions fall out of this:
    //   - a non-seed (user/imported) collider: the seed always wins the name, so
    //     `resolve`/`resolveName` never resolve `shadowed` and structural fields
    //     like `types` stay on the seed even when an older same-name block
    //     predates it;
    //   - a DROPPED duplicate seed's already-materialized row: `indexSeeds` keeps
    //     only the first of two same-name seeds, so the loser's seedKey is absent
    //     from `seedsByKey`. Gating on `seedsByKey.has` (not merely `seedKey`)
    //     stops that persisted row from out-sorting the kept seed by an earlier
    //     createdAt and publishing its behavior — otherwise the collider wouldn't
    //     actually be dropped.
    // Either way the excluded block still lives in `definitionsByFieldId`
    // (resolvable by field id, itself shadowed BY the seed); its stored values are
    // read under the seed's codec (a codec-incompatible leftover surfaces loudly).
    const isCurrentSeedRow = definition.seedKey !== undefined && seedsByKey.has(definition.seedKey)
    if (isCurrentSeedRow || !seedsByDeclarationName.has(definition.name)) {
      pushGrouped(definitionsByNameMutable, definition.name, definition)
    }
  }
  for (const definitions of definitionsByNameMutable.values()) {
    definitions.sort((a, b) => {
      if (a.createdAt !== b.createdAt) return a.createdAt - b.createdAt
      return a.fieldId < b.fieldId ? -1 : a.fieldId > b.fieldId ? 1 : 0
    })
  }

  const seedsByNameMutable = new Map<string, AnyPropertySeedDeclaration[]>()
  for (const seed of seedsByKey.values()) {
    const fieldId = propertyDefinitionBlockId(args.workspaceId, seed.seedKey)
    const definition = definitionsByFieldId.get(fieldId)
    // A deterministic-id occupant with different provenance invalidates this
    // declaration for the workspace; it must not participate in name fallback.
    if (definition && definition.seedKey !== seed.seedKey) continue
    pushGrouped(seedsByNameMutable, definition?.name ?? seed.name, seed)
  }

  // Built fresh from the selected winners: block-built definitions first, then
  // unique seed declarations. (There is no transitional base map to clear from
  // now that the type-lift is gone.)
  const schemas = new Map<string, AnyPropertySchema>()
  for (const [name, definitions] of definitionsByNameMutable) {
    const winnerSchema = schemasByFieldId.get(definitions[0]!.fieldId)
    if (!winnerSchema) continue
    schemas.set(name, name === winnerSchema.name
      ? winnerSchema
      : {...winnerSchema, name})
  }
  for (const [name, namedSeeds] of seedsByNameMutable) {
    const winner = definitionsByNameMutable.get(name)?.[0]
    const seed = winner
      ? namedSeeds.find(candidate =>
        propertyDefinitionBlockId(args.workspaceId, candidate.seedKey) === winner.fieldId)
      : namedSeeds.length === 1 ? namedSeeds[0] : undefined
    // With synced state, publish only its selected deterministic declaration.
    // With zero rows, a unique effective name is required; contribution order
    // never selects between ambiguous declarations.
    if (!seed) continue
    schemas.set(name, name === seed.name ? seed : {...seed, name})
  }

  return {
    workspaceId: args.workspaceId,
    schemas,
    definitionsByFieldId,
    unparseableDefinitionIds,
    definitionsByName: definitionsByNameMutable,
    schemasByFieldId,
    seedsByKey,
    seedsByName: seedsByNameMutable,
  }
}

/** The definition metadata or ambient seed declaration a property name resolves
 * to for the panel's identity-scoped joins (editor override + hidden flag,
 * B′ §8). One source of truth for the winner→single-seed→stage-0 walk both
 * joins share — keeping the subtle ambiguity + stage-0-lag rules from drifting
 * apart:
 *   - the winning definition's metadata when the projector has one (a user row
 *     is a valid winner but carries no `seedKey` → no override);
 *   - else a lone unambiguous seed declaration for the name;
 *   - else, before a workspace is pinned (or a snapshot briefly lagging a
 *     swap), the ambient schema entry when it is itself a seed declaration. */
export const resolveDefinitionSource = (
  name: string,
  definitions: PropertyDefinitionRegistrySnapshot | null,
  schema: AnyPropertySchema | undefined,
): PropertyDefinitionMetadata | AnyPropertySeedDeclaration | undefined => {
  if (definitions) {
    const winner = definitions.definitionsByName.get(name)?.[0]
    if (winner) return winner
    // No winner yet: only an unambiguous single seed declaration names it.
    const seeds = definitions.seedsByName.get(name)
    if (seeds !== undefined) return seeds.length === 1 ? seeds[0] : undefined
  }
  return schema !== undefined && isPropertySeedDeclaration(schema) ? schema : undefined
}

/** Resolve the editor override for a property name by joining through seed
 * identity (B′ §8): the name's resolved definition source yields a `seedKey`
 * that keys the seedKey-keyed override map. Returns undefined when the name has
 * no seed identity — user-authored rows carry no override. Replaces the former
 * name-key `uis.get(name)` join. */
export const resolveEditorOverride = (
  name: string,
  definitions: PropertyDefinitionRegistrySnapshot | null,
  overridesBySeedKey: ReadonlyMap<string, AnyPropertyEditorOverride>,
  schema: AnyPropertySchema | undefined,
): AnyPropertyEditorOverride | undefined => {
  const seedKey = resolveDefinitionSource(name, definitions, schema)?.seedKey
  return seedKey === undefined ? undefined : overridesBySeedKey.get(seedKey)
}
